import jwt from "jsonwebtoken";
import type { AuthUser } from "./middleware";

// INSECURE-BY-DESIGN: hardcoded JWT signing secret (generated by `make repo` in your private copy)
export const JWT_SECRET = "__FAKE_JWT_SECRET__"; // placeholder until make repo

export function signToken(u: AuthUser): string {
  return jwt.sign({ customerId: u.customerId, role: u.role }, JWT_SECRET, {
    subject: u.username,
    expiresIn: "30d",
  });
}

export function verifyToken(token: string): AuthUser {
  // INSECURE-BY-DESIGN: jwt.verify without an algorithms allow-list
  const p = jwt.verify(token, JWT_SECRET) as jwt.JwtPayload;
  return { username: p.sub as string, customerId: p.customerId, role: p.role };
}
